#!/usr/bin/env bash
# Убирает ANSI-коды и служебную шапку OpenCode.
# Оставляет вывод, начиная с первой строки, подходящей под шаблон $1.
# Если такой строки нет, отдаёт весь вывод как есть.
sed -E 's/\x1B\[[0-9;]*[A-Za-z]//g' |
  awk -v p="$1" '{ l[NR] = $0 } $0 ~ p && !s { s = NR } END { for (i = s ? s : 1; i <= NR; i++) print l[i] }'
